            } else if (path[startIndex + 2].isPathSeparator()) {
                3 // skip 3 characters: ../ or ..\
            } else { // we have a path component starting with two dots that shouldn't be discarded
                break
            }
        } else { // we have a path component starting with a single dot
            break
        }
    }

    return startIndex
