        }

        if (chunkStart < dateString.length) {
            builder.handleToken(current, dateString.substring(chunkStart))
        }
    } catch (_: Throwable) {
        throw InvalidDateStringException(dateString, chunkStart, pattern)
    }

    return builder.build()
}
