private fun buildPartialMatchTable(): IntArray {
    val table = IntArray(matchString.size)
    var j = 0

    for (i in 1 until matchString.size) {
        while (j > 0 && matchString[i] != matchString[j]) {
            j = table[j - 1]
        }
        if (matchString[i] == matchString[j]) {
            j++
        }
        table[i] = j
    }

    return table
}
