/** Formats an IPv6 address with the longest run of zero groups collapsed to :: per RFC 5952. Single zero groups are not collapsed; runs of length 2 or more are. */
internal fun formatIpv6(groups: IntArray): String {
    require(groups.size == 8) { "IPv6 address must have 8 groups, got ${groups.size}" }

    var bestStart = -1
    var bestLength = 0
    var currentStart = -1
    var currentLength = 0
    for (i in groups.indices) {
        if (groups[i] == 0) {
            if (currentStart == -1) currentStart = i
            currentLength++
            if (currentLength > bestLength) {
                bestStart = currentStart
                bestLength = currentLength
            }
        } else {
            currentStart = -1
            currentLength = 0
        }
    }
    if (bestLength < 2) {
        bestStart = -1
        bestLength = 0
    }

    return buildString {
        var i = 0
        while (i < 8) {
            if (i == bestStart) {
                append("::")
                i += bestLength
                continue
            }
            if (i > 0 && i != bestStart + bestLength) append(':')
            append(groups[i].toString(16))
            i++
        }
    }
}
