/** Launch a coroutine with [block] body when either the parent job or the returned job is cancelled. It is important to complete or cancel the returned [CompletableJob] otherwise the parent job will be unable to complete successfully. */
public fun Job.launchOnCancellation(block: suspend () -> Unit): CompletableJob {
    val completableJob: CompletableJob = Job(parent = this)

    GlobalScope.launch(this + Dispatchers.IOBridge + CoroutineName("cancellation-watcher")) {
        var cancelled = false
        try {
            completableJob.join()
        } catch (_: Throwable) {
            cancelled = true
        }

        if (cancelled || completableJob.isCancelled) {
            block()
        }
    }

    return completableJob
}
