/** Invokes [block] if it is possible to read at least [min] byte providing byte buffer to it so lambda can read from the buffer up to [ByteBuffer.available] bytes. If there are no [min] bytes available then the invocation returns 0. */
public fun ByteReadChannel.readAvailable(block: (ByteBuffer) -> Int): Int {
    if (isClosedForRead || readBuffer.exhausted()) return -1

    var result = 0
    UnsafeBufferOperations.readFromHead(readBuffer.buffer) { array, start, endExclusive ->
        val buffer = ByteBuffer.wrap(array, start, endExclusive - start)
        result = block(buffer)
        result
    }

    return result
}
```

