/** Replaces the current cached value with one computed with [block]. Only one [loadToken] or [setToken] call can be executed at a time, although the resumed [setToken] call recomputes the value cached by [loadToken]. */
internal suspend fun setToken(nonCancellable: Boolean = false, block: suspend () -> T?): T? {
    val prevValue = value
    val lockedByLoad = isLoadRequest

    val context = if (nonCancellable) {
        currentCoroutineContext() + NonCancellable + setTokenMarker
    } else {
        currentCoroutineContext() + setTokenMarker
    }
    return withContext(context) {
        mutex.withLock {
            if (prevValue == value || lockedByLoad) { // Raced first
                value = block()
            }
            value
        }
    }
}
