public fun Sequence<Route>.mapToPathItems(
    onOperation: OperationMapping = PopulateMediaTypeDefaults
): Map<String, PathItem> {
    return mapNotNull { node ->
        val isHidden = node.lineage()
            .any { OperationHiddenAttributeKey in it.attributes }
        if (isHidden) {
