        node.asPathItem(onOperation)
    }.fold(mutableMapOf()) { map, (route, pathItem) ->
        map.also {
            if (route in map) {
                map[route] = map[route]!! + pathItem
            } else {
                map[route] = pathItem
            }
        }
    }
}
