/** Appends each segment in path[start, end) to [parameters] under [name], matching [PathSegmentTailcardRouteSelector] capture semantics: empty segments (from //) are skipped and each part is URL-decoded (only paying the decode cost when a % is present). */
private fun captureTailcardSegments(
    addParameter: (String, String) -> Unit,
    name: String,
    path: String,
    start: Int,
    end: Int,
) {
    var segStart = start
    while (segStart < end) {
        var segEnd = segStart
        var hasPercent = false
        while (segEnd < end) {
            val c = path[segEnd]
            if (c == '/') break
            if (c == '%') hasPercent = true
            segEnd++
        }
        if (segEnd != segStart) { // skip empty segments produced by consecutive '/'
            addParameter(name, decodeSegment(path.substring(segStart, segEnd), hasPercent))
        }
        segStart = segEnd + 1
    }
}
