public actual fun YamlConfig(path: String?): YamlConfig? {
    val resolvedPath = when {
        path != null && (path.endsWith(".yaml") || path.endsWith(".yml")) -> path
        path == null && access(DEFAULT_YAML_FILENAME, F_OK) == 0 -> DEFAULT_YAML_FILENAME
        else -> null
