/** Attempts to acquire the lock. If the lock is available, it will be acquired, and this function will return true. If the lock is already held by another thread, this function will return false immediately without blocking. */
public fun tryLock(): Boolean {
    val currentThreadId = pthread_self()
    while (true) {
        val state = lock.value
        if (state.status == Status.UNLOCKED) {
            val thinLock = LockState(Status.THIN, 1, 0, currentThreadId)
            if (lock.compareAndSet(state, thinLock)) {
                return true
            }
        } else {
            if (currentThreadId == state.ownerThreadId) {
                val nestedLock = LockState(
                    state.status,
                    state.nestedLocks + 1,
                    state.waiters,
                    currentThreadId,
                    state.mutex
                )
                if (lock.compareAndSet(state, nestedLock)) {
                    return true
                }
            } else {
                return false
            }
        }
    }
