/** Await the [NettyApplicationCall.responseWriteJob] to complete if the response status is informational or 204. Netty discards certain headers of such responses, so we have to wait for Netty to finish that, in order to avoid the race condition. */
private suspend fun awaitProcessingResponseIfInfoOrNoContent() {
    val status = status()

    if (status != null) {
        val infoOrNoContent = status == HttpStatusCode.NoContent || (status.value >= 100 && status.value < 200)

        if (infoOrNoContent && call is NettyApplicationCall) {
            (call as NettyApplicationCall).responseWriteJob.join()
        }
    }
}
